<?php
require_once __DIR__.'/../bootstrap.php';
$user=current_user();if(!in_array($user['role_name'],['ADMIN','HR'],true))api_response(['error'=>'HR authorization required.'],403);if($_SERVER['REQUEST_METHOD']!=='POST')api_response(['error'=>'POST required.'],405);verify_csrf();$id=(int)($_GET['id']??0);$action=strtoupper((string)($_GET['action']??''));$allowed=['PROMOTION','TRANSFER','REGULARIZE','RESIGN','TERMINATE'];$map=['PROMOTION'=>'PROMOTION','TRANSFER'=>'TRANSFER','REGULARIZE'=>'REGULARIZATION','RESIGN'=>'RESIGNATION','TERMINATE'=>'TERMINATION'];if(!isset($map[$action]))api_response(['error'=>'Unsupported lifecycle action.'],422);$input=api_input();$changes=[];foreach(['department_id','position_id','branch_id'] as $field)if(isset($input[$field]))$changes[$field]=(int)$input[$field];if($action==='REGULARIZE'){$changes['employment_status']='Active';$changes['employment_type']='Regular';}if(in_array($action,['RESIGN','TERMINATE'],true))$changes['employment_status']='Separated';try{lifecycle(db(),$id,$map[$action],$changes,(string)($input['reason']??''),(string)($input['effective_date']??date('Y-m-d')));api_response(['message'=>'Lifecycle action recorded.']);}catch(Throwable $exception){api_response(['error'=>'Lifecycle action failed.'],422);}